package dev.sablelife.testing;
import java.util.*;
import dev.sablelife.SableLife;
import dev.sablelife.heart.*;
import dev.sablelife.module.*;
import dev.sablelife.attack.*;
import dev.sablelife.ownership.LoadedCoreIndex;
import dev.sablelife.compat.sable.SableBodyProbe;
import dev.ryanhcode.sable.api.SubLevelAssemblyHelper;
import dev.ryanhcode.sable.companion.math.BoundingBox3i;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.network.chat.*;
import net.minecraft.network.chat.contents.TranslatableContents;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.projectile.Arrow;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.*;
import net.neoforged.neoforge.gametest.*;
@GameTestHolder("sablelife_owner_tests") @PrefixGameTestTemplate(false)
public final class OwnerPlayerGameTests {
    private static HeartBlockEntity core(GameTestHelper h){var l=h.getLevel();var p=h.absolutePos(new BlockPos(4,40,4));l.setBlockAndUpdate(p,SableLife.HEART.get().defaultBlockState());l.setBlockAndUpdate(p.east(),Blocks.IRON_BLOCK.defaultBlockState());var body=SubLevelAssemblyHelper.assembleBlocks(l,p,List.of(p,p.east()),new BoundingBox3i(p.getX(),p.getY(),p.getZ(),p.getX()+1,p.getY(),p.getZ()));var c=(HeartBlockEntity)l.getBlockEntity(body.getPlot().getCenterBlock());c.tryActivate(TestActors.creative(l));LoadedCoreIndex.observe(c);return c;}
    private static net.neoforged.neoforge.common.util.FakePlayer player(GameTestHelper h,Vec3 pos){var p=net.neoforged.neoforge.common.util.FakePlayerFactory.get(h.getLevel(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"Own"+UUID.randomUUID().toString().substring(0,8)));p.setGameMode(GameType.CREATIVE);p.setNoGravity(true);h.getLevel().addNewPlayer(p);p.setPos(pos);return p;}
    private static VirtualModule mark(HeartBlockEntity c,String type){var m=c.modules().add(type);m.anchors(List.of(ModuleAnchor.create(c,c.getBlockPos().east(),Direction.NORTH)));return m;}
    private static Component killer(Component message){return (Component)((TranslatableContents)message.getContents()).getArgs()[1];}
    @GameTest(template="combat",batch="owner_settings")
    public static void OwnerSettingsPersistCopyValidateAndRetainLivePermissions(GameTestHelper h){var c=core(h);var author=TestActors.creative(h.getLevel());author.setPos(SableBodyProbe.toWorld(h.getLevel(),c.getBlockPos().getCenter()));var menu=new HeartSettingsMenu(1,author.getInventory(),c);h.assertTrue(menu.action(author,"ownerName",0,"TestOwner")&&menu.snapshot().getString("ownerName").equals("TestOwner"),"Owner did not sync while alive");var saved=c.copyConfiguration();h.assertTrue(saved.getCompound("Relations").getString("OwnerName").equals("TestOwner"),"Owner lost in config copy");var r=new CoreRelations();r.load(c.relations().save());h.assertTrue(r.ownerName().equals("TestOwner"),"Owner lost in save");h.assertTrue(!menu.action(author,"ownerName",0,"Bad Name")&&!menu.action(author,"ownerName",0,"x".repeat(17)),"Invalid owner accepted");author.setGameMode(GameType.SURVIVAL);h.assertTrue(!menu.action(author,"ownerName",0,"Another"),"Survival changed owner");author.setGameMode(GameType.CREATIVE);h.assertTrue(menu.action(author,"ownerName",0,""),"Owner cannot be cleared");r.load(new net.minecraft.nbt.CompoundTag());h.assertTrue(r.ownerName().isEmpty(),"Legacy owner not empty");h.succeed();}
    @GameTest(template="combat",batch="owner_follow")
    public static void OwnerFollowBypassesExclusionWithoutSelectingNearbyOtherPlayers(GameTestHelper h){var c=core(h);var center=SableBodyProbe.toWorld(h.getLevel(),c.getBlockPos().getCenter());var p=player(h,center.add(0,0,8));var other=player(h,center.add(2,0,0));c.relations().ownerName(p.getGameProfile().getName().toLowerCase(Locale.ROOT));c.relations().exclude(p.getGameProfile().getName());var m=mark(c,"auto_facing");m.edit("target",4,"");h.assertTrue(ModuleAutoFacing.selectTarget(h.getLevel(),c,m,center)==p,"Owner selection did not bypass exclusion/creative rules");m.edit("facingRange",4,"");h.assertTrue(ModuleAutoFacing.selectTarget(h.getLevel(),c,m,center)==null,"Out-of-range Owner fell back to stranger");m.edit("facingRange",16,"");c.relations().ownerName("Offline_User");h.assertTrue(ModuleAutoFacing.selectTarget(h.getLevel(),c,m,center)==null,"Missing Owner fell back to stranger");p.discard();other.discard();h.succeed();}
    @GameTest(template="combat",batch="owner_movement")
    public static void MovementAndNavigationResolveOnlyConfiguredOwner(GameTestHelper h){var c=core(h);var center=SableBodyProbe.toWorld(h.getLevel(),c.getBlockPos().getCenter());var p=player(h,center.add(0,0,8));c.relations().ownerName(p.getGameProfile().getName());c.relations().exclude(p.getGameProfile().getName());var m=mark(c,"linear_movement");m.edit("moveAim",1,"");m.edit("target",4,"");h.assertTrue(ModuleLinearMovement.plan(c,m)!=null,"Owner movement cannot find excluded owner");h.assertTrue(ModuleTargets.resolveForModule(h.getLevel(),p.getUUID(),c,mark(c,"navigation"))==null,"Ordinary navigation bypassed exclusion");var nav=mark(c,"navigation");nav.edit("target",4,"");h.assertTrue(ModuleTargets.resolveForModule(h.getLevel(),p.getUUID(),c,nav)==p,"Owner navigation resolve failed");var n=new TargetNavigation();n.tick(h.getLevel(),c,nav,new HashMap<>());h.assertTrue(n.name(nav.id()).equals(p.getGameProfile().getName()),"Owner navigation did not lock owner");p.discard();h.assertTrue(ModuleLinearMovement.plan(c,m)==null,"Removed owner retained movement target");h.succeed();}
    @GameTest(template="combat",batch="owner_sensor")
    public static void TargetSensorDetectsOwnerIncludingCreativeAndExcludedPlayers(GameTestHelper h){var c=core(h);var sensor=mark(c,"sensor");sensor.edit("target",4,"");sensor.edit("lineOfSight",1,"");var center=sensor.anchors().getFirst().world(c,false);var p=player(h,center.add(0,0,4));var stranger=player(h,center.add(0,0,2));c.relations().ownerName(p.getGameProfile().getName());c.relations().exclude(p.getGameProfile().getName());c.modules().events().tick(c);h.assertTrue(c.modules().events().sensorDetected(sensor.id()),"Sensor cannot detect excluded creative Owner");c.relations().ownerName("Offline_User");c.modules().events().tick(c);h.assertTrue(!c.modules().events().sensorDetected(sensor.id()),"Owner sensor substituted a stranger");p.discard();stranger.discard();h.succeed();}
    @GameTest(template="combat",batch="owner_safety")
    public static void AttackTargetsAndDamageNeverTreatOwnerAsEnemy(GameTestHelper h){var c=core(h);var p=player(h,SableBodyProbe.toWorld(h.getLevel(),c.getBlockPos().getCenter()).add(0,0,4));p.setGameMode(GameType.SURVIVAL);c.relations().ownerName(p.getGameProfile().getName());for(var type:List.of("gun","arrow","laser","slash"))h.assertTrue(ModuleFields.find(type,"target").choices().size()==4,"Attack gained Owner choice");var bounds=p.getBoundingBox().inflate(2);h.assertTrue(!ModuleTargets.query(h.getLevel(),c.creatureId(),bounds,e->true).contains(p)&&!ModuleTargets.damageQuery(h.getLevel(),c.creatureId(),bounds,e->true).contains(p),"Owner appeared in attack selection/hit volume");float before=p.getHealth();h.assertTrue(!ModuleDamage.hurt(p,ModuleDamage.named(ModuleDamage.physical(h.getLevel()),c),10)&&p.getHealth()==before,"Owner took module damage");var arrow=new Arrow(EntityType.ARROW,h.getLevel());ModuleDamage.nameProjectile(arrow,c);AttackHitCredit.attach(arrow,c,new VirtualModule("arrow"));h.assertTrue(!p.hurt(h.getLevel().damageSources().arrow(arrow,null),10)&&p.getHealth()==before,"Native arrow bypassed Owner protection");p.discard();h.succeed();}
    @GameTest(template="combat",batch="owner_death")
    public static void OwnedDeathMessagesPreserveStyleAndProjectileLaunchSnapshot(GameTestHelper h){var c=core(h);c.editCore(TestActors.creative(h.getLevel()),"name",0,"&c&lCore");c.relations().ownerName("TestOwner");var victim=EntityType.ZOMBIE.create(h.getLevel());var source=ModuleDamage.named(ModuleDamage.physical(h.getLevel()),c);var name=killer(source.getLocalizedDeathMessage(victim));h.assertTrue(name.equals(CreatureNames.killer("&c&lCore","TestOwner")),"Direct Owner death name incorrect");var body=ModuleDamage.named(new BodyMeleeSource(h.getLevel(),Vec3.ZERO,"&c&lCore"),c);h.assertTrue(killer(body.getLocalizedDeathMessage(victim)).equals(name),"Melee Owner death name missing");var arrow=new Arrow(EntityType.ARROW,h.getLevel());ModuleDamage.nameProjectile(arrow,c);var tag=arrow.saveWithoutId(new net.minecraft.nbt.CompoundTag());var loaded=new Arrow(EntityType.ARROW,h.getLevel());loaded.load(tag);c.relations().ownerName("Later_User");h.assertTrue(killer(h.getLevel().damageSources().arrow(loaded,null).getLocalizedDeathMessage(victim)).equals(name),"Arrow lost launch Owner after reload/change");c.relations().ownerName("");h.assertTrue(killer(ModuleDamage.named(ModuleDamage.physical(h.getLevel()),c).getLocalizedDeathMessage(victim)).equals(CreatureNames.killer("&c&lCore")),"Empty Owner changed legacy death text");h.succeed();}
}
